## Design Note

- **Tokenizer** → token list with positions; **Parser** → iterative state machine (explicit stack, no recursion) that emits stack-based bytecode directly; **Evaluation** → flat instruction loop over immutable tuple.
- Data: bytecode = tuple of `(opcode, arg1, arg2)` tuples; `if` compiled to `JMP_IF_FALSE`/`JMP` for laziness.
- Complexity: compile O(n), evaluate O(instructions). No recursion in parse or eval → handles 100 k nesting.
- Concurrency: `Expr` is immutable post-compile; `evaluate` uses only local stack → thread-safe without locks.

### solution.py
```python
"""Safe formula engine for spreadsheet cells – standard library only."""

import math
from typing import Mapping

# ─── Exceptions ────────────────────────────────────────────────────────────────

class ExprError(Exception):
    pass

class ExprSyntaxError(ExprError):
    def __init__(self, message: str, position: int):
        self.message = message
        self.position = position
        super().__init__(message)

class ExprNameError(ExprError):
    def __init__(self, name: str):
        self.name = name
        super().__init__(f"unknown name: {name}")

class ExprEvalError(ExprError):
    pass

# ─── Token kinds ───────────────────────────────────────────────────────────────

_TOK_NUM   = 0
_TOK_IDENT = 1
_TOK_OP    = 2   # + - * / % ^
_TOK_CMP   = 3   # < <= > >= == !=
_TOK_LPAREN = 4
_TOK_RPAREN = 5
_TOK_COMMA  = 6
_TOK_EOF    = 7
_TOK_INVALID = 8

# ─── Opcodes ───────────────────────────────────────────────────────────────────

_OP_NUM    = 0
_OP_VAR    = 1
_OP_ADD    = 2
_OP_SUB    = 3
_OP_MUL    = 4
_OP_DIV    = 5
_OP_MOD    = 6
_OP_POW    = 7
_OP_NEG    = 8
_OP_POS    = 9
_OP_LT     = 10
_OP_LE     = 11
_OP_GT     = 12
_OP_GE     = 13
_OP_EQ     = 14
_OP_NE     = 15
_OP_CALL   = 16
_OP_JMPF   = 17  # jump if false (for lazy if)
_OP_JMP    = 18

# ─── Function table ────────────────────────────────────────────────────────────

# name -> (min_args, max_args); max_args == -1 means unlimited
_FUNCS = {
    'abs':   (1, 1),
    'sqrt':  (1, 1),
    'min':   (1, -1),
    'max':   (1, -1),
    'round': (1, 2),
    'if':    (3, 3),
}

# ─── Tokenizer ─────────────────────────────────────────────────────────────────

class _Token:
    __slots__ = ('kind', 'val', 'pos')
    def __init__(self, kind, val, pos):
        self.kind = kind
        self.val = val
        self.pos = pos

def _is_digit(c):
    return '0' <= c <= '9'

def _is_alpha(c):
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'

def _is_alnum(c):
    return _is_alpha(c) or _is_digit(c)

def _tokenize(src: str):
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        # whitespace
        if c == ' ' or c == '\t' or c == '\n' or c == '\r':
            i += 1
            continue
        # number
        if _is_digit(c) or (c == '.' and i + 1 < n and _is_digit(src[i + 1])):
            start = i
            while i < n and _is_digit(src[i]):
                i += 1
            if i < n and src[i] == '.':
                i += 1
                while i < n and _is_digit(src[i]):
                    i += 1
            # exponent
            if i < n and (src[i] == 'e' or src[i] == 'E'):
                i += 1
                if i < n and (src[i] == '+' or src[i] == '-'):
                    i += 1
                exp_start = i
                while i < n and _is_digit(src[i]):
                    i += 1
                if i == exp_start:
                    raise ExprSyntaxError("malformed number", start)
            text = src[start:i]
            val = float(text)
            if math.isinf(val):
                raise ExprSyntaxError("number too large", start)
            tokens.append(_Token(_TOK_NUM, val, start))
            continue
        # identifier
        if _is_alpha(c):
            start = i
            while i < n and _is_alnum(src[i]):
                i += 1
            tokens.append(_Token(_TOK_IDENT, src[start:i], start))
            continue
        # punctuation / operators
        if c == '(':
            tokens.append(_Token(_TOK_LPAREN, '(', i)); i += 1; continue
        if c == ')':
            tokens.append(_Token(_TOK_RPAREN, ')', i)); i += 1; continue
        if c == ',':
            tokens.append(_Token(_TOK_COMMA, ',', i)); i += 1; continue
        if c in '+-*/%^':
            tokens.append(_Token(_TOK_OP, c, i)); i += 1; continue
        if c == '<':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append(_Token(_TOK_CMP, '<=', i)); i += 2
            else:
                tokens.append(_Token(_TOK_CMP, '<', i)); i += 1
            continue
        if c == '>':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append(_Token(_TOK_CMP, '>=', i)); i += 2
            else:
                tokens.append(_Token(_TOK_CMP, '>', i)); i += 1
            continue
        if c == '=':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append(_Token(_TOK_CMP, '==', i)); i += 2
            else:
                tokens.append(_Token(_TOK_INVALID, '=', i)); i += 1
            continue
        if c == '!':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append(_Token(_TOK_CMP, '!=', i)); i += 2
            else:
                tokens.append(_Token(_TOK_INVALID, '!', i)); i += 1
            continue
        # invalid character
        tokens.append(_Token(_TOK_INVALID, c, i)); i += 1
    tokens.append(_Token(_TOK_EOF, None, n))
    return tokens

# ─── Precedence helpers ────────────────────────────────────────────────────────

_BIN_PREC = {'+': 2, '-': 2, '*': 3, '/': 3, '%': 3}
_CMP_PREC = 1

def _op_code(op):
    return {'+': _OP_ADD, '-': _OP_SUB, '*': _OP_MUL, '/': _OP_DIV,
            '%': _OP_MOD, '^': _OP_POW}[op]

def _cmp_code(op):
    return {'<': _OP_LT, '<=': _OP_LE, '>': _OP_GT, '>=': _OP_GE,
            '==': _OP_EQ, '!=': _OP_NE}[op]

# ─── Iterative Parser ─────────────────────────────────────────────────────────

def _parse(tokens, src_len):
    """Iterative Pratt-style parser → bytecode list. No recursion."""
    n = len(tokens)
    bc = []          # bytecode (list of tuples, will become tuple)
    variables = set()
    calls = []       # (name, nargs, pos) for post-parse validation
    pos = 0          # token index
    stack = []       # explicit parser stack

    # Modes
    _OPERAND = 0
    _POWER   = 1
    _BINARY  = 2
    _DONE    = 3

    mode = _OPERAND
    min_prec = 1  # current expression minimum precedence

    while True:
        # ── OPERAND mode: parse unary prefixes then a primary ──
        if mode == _OPERAND:
            # unary + / -
            if pos < n and tokens[pos].kind == _TOK_OP and tokens[pos].val in ('+', '-'):
                stack.append(('u', tokens[pos].val, min_prec))
                pos += 1
                min_prec = 6  # operand of unary is a term-operand (no binary)
                continue  # stay in OPERAND to check for more unary or primary

            if pos >= n:
                raise ExprSyntaxError("unexpected end of input", src_len)

            tok = tokens[pos]

            if tok.kind == _TOK_NUM:
                bc.append((_OP_NUM, tok.val, 0))
                pos += 1
                mode = _POWER
                continue

            if tok.kind == _TOK_IDENT:
                # check for function call: next token is LPAREN
                if pos + 1 < n and tokens[pos + 1].kind == _TOK_LPAREN:
                    fname = tok.val
                    fpos = tok.pos
                    pos += 2  # skip IDENT and (
                    # empty arg list?
                    if pos < n and tokens[pos].kind == _TOK_RPAREN:
                        pos += 1
                        bc.append((_OP_CALL, fname, 0))
                        calls.append((fname, 0, fpos))
                        mode = _POWER
                        continue
                    # first argument
                    stack.append(('call', fname, fpos, 0, min_prec,
                                  {'j0': -1, 'j1': -1} if fname == 'if' else None))
                    min_prec = 1
                    mode = _OPERAND
                    continue
                else:
                    bc.append((_OP_VAR, tok.val, 0))
                    variables.add(tok.val)
                    pos += 1
                    mode = _POWER
                    continue

            if tok.kind == _TOK_LPAREN:
                pos += 1
                stack.append(('paren', min_prec))
                min_prec = 1
                mode = _OPERAND
                continue

            # not a valid operand start
            raise ExprSyntaxError(
                f"unexpected token: {tok.val!r}" if tok.val is not None else "unexpected end",
                tok.pos)

        # ── POWER mode: just finished a primary, check for ^ ──
        if mode == _POWER:
            if pos < n and tokens[pos].kind == _TOK_OP and tokens[pos].val == '^':
                pos += 1
                stack.append(('p', min_prec))
                min_prec = 6  # exponent is a unary (no binary ops)
                mode = _OPERAND
                continue
            mode = _BINARY
            continue

        # ── BINARY mode: check for binary / comparison operators ──
        if mode == _BINARY:
            if pos < n:
                tok = tokens[pos]
                if tok.kind == _TOK_OP and tok.val in _BIN_PREC:
                    prec = _BIN_PREC[tok.val]
                    if prec >= min_prec:
                        pos += 1
                        right_prec = prec + 1  # left-assoc
                        stack.append(('b', tok.val, min_prec))
                        min_prec = right_prec
                        mode = _OPERAND
                        continue
                if tok.kind == _TOK_CMP and _CMP_PREC >= min_prec:
                    pos += 1
                    stack.append(('c', tok.val, min_prec))
                    min_prec = 2  # after cmp, can't consume another cmp
                    mode = _OPERAND
                    continue
            # no operator consumed → expression at this level is done
            mode = _DONE
            continue

        # ── DONE: pop stack ──
        if mode == _DONE:
            if not stack:
                # top-level: check for trailing tokens
                if pos < n and tokens[pos].kind != _TOK_EOF:
                    raise ExprSyntaxError(
                        f"unexpected token: {tokens[pos].val!r}",
                        tokens[pos].pos)
                break  # parsing complete

            frame = stack.pop()
            kind = frame[0]

            if kind == 'u':
                # unary +/-: apply
                bc.append((_OP_NEG if frame[1] == '-' else _OP_POS, 0, 0))
                min_prec = frame[2]
                mode = _BINARY
                continue

            if kind == 'p':
                # power: apply ^
                bc.append((_OP_POW, 0, 0))
                min_prec = frame[1]
                mode = _BINARY
                continue

            if kind == 'b':
                # binary + - * / %
                bc.append((_op_code(frame[1]), 0, 0))
                min_prec = frame[2]
                mode = _BINARY
                continue

            if kind == 'c':
                # comparison
                bc.append((_cmp_code(frame[1]), 0, 0))
                min_prec = frame[2]
                mode = _BINARY
                continue

            if kind == 'paren':
                # expect )
                if pos >= n or tokens[pos].kind != _TOK_RPAREN:
                    raise ExprSyntaxError("expected ')'",
                                          tokens[pos].pos if pos < n else src_len)
                pos += 1
                min_prec = frame[1]
                mode = _POWER
                continue

            if kind == 'call':
                _, fname, fpos, nargs, outer_mp, if_data = frame
                # after an argument, expect , or )
                if pos < n and tokens[pos].kind == _TOK_COMMA:
                    pos += 1
                    # special: for 'if', emit jump placeholders after arg 0 and arg 1
                    if if_data is not None:
                        if nargs == 0:
                            if_data['j0'] = len(bc)
                            bc.append((_OP_JMPF, 0, 0))
                        elif nargs == 1:
                            if_data['j1'] = len(bc)
                            bc.append((_OP_JMP, 0, 0))
                    nargs += 1
                    stack.append(('call', fname, fpos, nargs, outer_mp, if_data))
                    min_prec = 1
                    mode = _OPERAND
                    continue
                elif pos < n and tokens[pos].kind == _TOK_RPAREN:
                    pos += 1
                    nargs += 1
                    if if_data is not None and nargs == 3:
                        # patch jumps
                        j0 = if_data['j0']
                        j1 = if_data['j1']
                        # JMP_IF_FALSE target = start of arg3 = j1 + 1
                        bc[j0] = (_OP_JMPF, j1 + 1, 0)
                        # JMP target = end of bytecode = len(bc)
                        bc[j1] = (_OP_JMP, len(bc), 0)
                    else:
                        bc.append((_OP_CALL, fname, nargs))
                    calls.append((fname, nargs, fpos))
                    min_prec = outer_mp
                    mode = _POWER
                    continue
                else:
                    raise ExprSyntaxError("expected ',' or ')'",
                                          tokens[pos].pos if pos < n else src_len)

            # should not reach here
            raise AssertionError(f"unknown frame {kind}")

    return bc, frozenset(variables), calls

# ─── Post-parse validation ─────────────────────────────────────────────────────

def _validate(calls):
    """Check function names and arg counts. Report leftmost error."""
    for name, nargs, pos in calls:
        if name not in _FUNCS:
            raise ExprNameError(name)
        lo, hi = _FUNCS[name]
        if nargs < lo or (hi != -1 and nargs > hi):
            raise ExprSyntaxError(
                f"{name}() expects {'1 or more' if hi == -1 else f'{lo}'}"
                f"{' to ' + str(hi) if hi != -1 and hi != lo else ''}"
                f" argument{'s' if (hi != 1 and hi != -1) or lo > 1 else ''},"
                f" got {nargs}", pos)

# ─── Expr class ────────────────────────────────────────────────────────────────

class Expr:
    __slots__ = ('source', 'variables', '_bc')

    def __init__(self, source: str, variables: frozenset, bc: tuple):
        self.source = source
        self.variables = variables
        self._bc = bc  # immutable tuple of (opcode, arg1, arg2)

    def evaluate(self, variables: Mapping[str, float] | None = None) -> float:
        bc = self._bc
        stack: list[float] = []
        pc = 0
        while pc < len(bc):
            op, a, b = bc[pc]
            if op == _OP_NUM:
                stack.append(a)
            elif op == _OP_VAR:
                if variables is None:
                    raise ExprNameError(a)
                try:
                    val = float(variables[a])
                except KeyError:
                    raise ExprNameError(a) from None
                except (TypeError, ValueError):
                    raise ExprEvalError(f"cannot convert variable '{a}' to float") from None
                if not math.isfinite(val):
                    raise ExprEvalError(f"variable '{a}' is not finite")
                stack.append(val)
            elif op == _OP_ADD:
                bv = stack.pop(); av = stack.pop(); stack.append(av + bv)
            elif op == _OP_SUB:
                bv = stack.pop(); av = stack.pop(); stack.append(av - bv)
            elif op == _OP_MUL:
                bv = stack.pop(); av = stack.pop(); stack.append(av * bv)
            elif op == _OP_DIV:
                bv = stack.pop(); av = stack.pop()
                if bv == 0.0:
                    raise ExprEvalError("division by zero")
                stack.append(av / bv)
            elif op == _OP_MOD:
                bv = stack.pop(); av = stack.pop()
                if bv == 0.0:
                    raise ExprEvalError("modulo by zero")
                stack.append(av % bv)
            elif op == _OP_POW:
                bv = stack.pop(); av = stack.pop()
                if av == 0.0 and bv < 0.0:
                    raise ExprEvalError("zero to negative power")
                if av < 0.0 and not bv.is_integer():
                    raise ExprEvalError("negative base to non-integer power")
                try:
                    rv = av ** bv
                except (ValueError, OverflowError):
                    raise ExprEvalError("power result undefined") from None
                if not math.isfinite(rv):
                    raise ExprEvalError("power result not finite")
                stack.append(rv)
            elif op == _OP_NEG:
                stack.append(-stack.pop())
            elif op == _OP_POS:
                pass  # no-op, value already on stack
            elif op == _OP_LT:
                bv = stack.pop(); av = stack.pop(); stack.append(1.0 if av < bv else 0.0)
            elif op == _OP_LE:
                bv = stack.pop(); av = stack.pop(); stack.append(1.0 if av <= bv else 0.0)
            elif op == _OP_GT:
                bv = stack.pop(); av = stack.pop(); stack.append(1.0 if av > bv else 0.0)
            elif op == _OP_GE:
                bv = stack.pop(); av = stack.pop(); stack.append(1.0 if av >= bv else 0.0)
            elif op == _OP_EQ:
                bv = stack.pop(); av = stack.pop(); stack.append(1.0 if av == bv else 0.0)
            elif op == _OP_NE:
                bv = stack.pop(); av = stack.pop(); stack.append(1.0 if av != bv else 0.0)
            elif op == _OP_CALL:
                name = a; nargs = b
                args = [stack.pop() for _ in range(nargs)][::-1]
                result = _call_func(name, args)
                stack.append(result)
            elif op == _OP_JMPF:
                if stack.pop() == 0.0:
                    pc = a
                    continue
            elif op == _OP_JMP:
                pc = a
                continue
            pc += 1
        return stack[0]

def _call_func(name, args):
    if name == 'abs':
        return abs(args[0])
    if name == 'sqrt':
        if args[0] < 0.0:
            raise ExprEvalError("sqrt of negative number")
        return math.sqrt(args[0])
    if name == 'min':
        return min(args)
    if name == 'max':
        return max(args)
    if name == 'round':
        if len(args) == 1:
            return float(round(args[0]))
        n = args[1]
        if not n.is_integer():
            raise ExprEvalError("round digit count is not integer-valued")
        return float(round(args[0], int(n)))
    # 'if' handled via jumps, should never reach here
    raise ExprEvalError(f"unknown function: {name}")

# ─── Public API ────────────────────────────────────────────────────────────────

def compile_expr(src: str) -> Expr:
    if not isinstance(src, str):
        raise TypeError(f"expected str, got {type(src).__name__}")
    tokens = _tokenize(src)
    bc, variables, calls = _parse(tokens, len(src))
    _validate(calls)
    return Expr(src, variables, tuple(bc))

def evaluate(src: str, variables: Mapping[str, float] | None = None) -> float:
    return compile_expr(src).evaluate(variables)
