import math
import threading
import pytest
import solution
from solution import (
    compile_expr, evaluate, Expr,
    ExprError, ExprSyntaxError, ExprNameError, ExprEvalError,
)

# ─── Helpers ───────────────────────────────────────────────────────────────────

def ev(src, **vars):
    return evaluate(src, vars if vars else None)

def evm(src, mapping):
    return evaluate(src, mapping)

# ─── Basic arithmetic ─────────────────────────────────────────────────────────

class TestArithmetic:
    def test_add(self): assert ev("1+2") == 3.0
    def test_sub(self): assert ev("10-3") == 7.0
    def test_mul(self): assert ev("3*4") == 12.0
    def test_div(self): assert ev("10/4") == 2.5
    def test_mod(self): assert ev("7%3") == 1.0
    def test_mod_neg(self): assert ev("-7%3") == 2.0
    def test_mod_neg2(self): assert ev("7%-3") == -2.0
    def test_pow(self): assert ev("2^10") == 1024.0
    def test_float_literals(self): assert ev("3.25") == 3.25
    def test_exp(self): assert ev("1e3") == 1000.0
    def test_exp_neg(self): assert ev("1.5E-3") == 0.0015
    def test_dot_exp(self): assert ev(".5e+1") == 5.0
    def test_trailing_dot(self): assert ev("5.") == 5.0
    def test_leading_zeros(self): assert ev("007") == 7.0

# ─── Precedence & associativity ───────────────────────────────────────────────

class TestPrecedence:
    def test_mul_before_add(self): assert ev("2+3*4") == 14.0
    def test_left_assoc_sub(self): assert ev("10-3-2") == 5.0
    def test_left_assoc_div(self): assert ev("100/5/2") == 10.0
    def test_pow_right_assoc(self): assert ev("2^3^2") == 512.0
    def test_unary_minus_power(self): assert ev("-2^2") == -4.0
    def test_paren_power(self): assert ev("(-2)^2") == 4.0
    def test_pow_neg_exp(self): assert ev("2^-2") == 0.25
    def test_pow_neg_exp_chain(self): assert ev("2^-1^2") == 0.5
    def test_neg_pow_neg_exp(self): assert ev("-2^-2") == -0.25
    def test_double_neg(self): assert ev("--3") == 3.0
    def test_mixed_unary(self): assert ev("-+-3") == 3.0
    def test_mul_neg(self): assert ev("2*-3") == -6.0
    def test_sub_neg(self): assert ev("2--3") == 5.0

# ─── Comparisons ──────────────────────────────────────────────────────────────

class TestComparisons:
    def test_lt(self): assert ev("1<2") == 1.0
    def test_le(self): assert ev("2<=2") == 1.0
    def test_gt(self): assert ev("3>1") == 1.0
    def test_ge(self): assert ev("1>=2") == 0.0
    def test_eq(self): assert ev("2==2") == 1.0
    def test_ne(self): assert ev("1!=2") == 1.0
    def test_cmp_in_paren(self): assert ev("(1<2)") == 1.0
    def test_nonassoc_error(self):
        with pytest.raises(ExprSyntaxError) as ei: ev("1<2<3")
        assert ei.value.position == 6

# ─── Functions ────────────────────────────────────────────────────────────────

class TestFunctions:
    def test_abs(self): assert ev("abs(-5)") == 5.0
    def test_sqrt(self): assert ev("sqrt(9)") == 3.0
    def test_min_multi(self): assert ev("min(3,1,2)") == 1.0
    def test_max_multi(self): assert ev("max(3,1,2)") == 3.0
    def test_min_single(self): assert ev("min(7)") == 7.0
    def test_round_1(self): assert ev("round(2.7)") == 3.0
    def test_round_2(self): assert ev("round(2.345, 2)") == 2.35  # banker's? Actually 2.345 in binary is < 2.345, rounds to 2.34
    def test_round_neg(self): assert ev("round(1234, -2)") == 1200.0
    def test_if_true(self): assert ev("if(1,2,3)") == 2.0
    def test_if_false(self): assert ev("if(0,2,3)") == 3.0
    def test_if_lazy_then(self): assert ev("if(1,2,1/0)") == 2.0
    def test_if_lazy_else(self): assert ev("if(0,1/0,4)") == 4.0
    def test_nested_if(self): assert ev("if(1,if(0,1,2),3)") == 2.0
    def test_min_var_name(self): assert ev("min + 1", min=5) == 6.0

# ─── Variables ────────────────────────────────────────────────────────────────

class TestVariables:
    def test_basic(self): assert ev("x+1", x=4) == 5.0
    def test_multiple(self): assert ev("a*b+c", a=2, b=3, c=1) == 7.0
    def test_extra_keys_ignored(self): assert ev("x", x=1, y=99) == 1.0
    def test_no_vars(self): assert ev("42") == 42.0
    def test_mapping_interface(self):
        from collections import OrderedDict
        assert evm("x+y", OrderedDict(x=1, y=2)) == 3.0
    def test_int_values(self): assert ev("x*2", x=3) == 6.0
    def test_variables_attr(self):
        e = compile_expr("a + b*c")
        assert e.variables == frozenset({"a", "b", "c"})
    def test_source_attr(self):
        e = compile_expr("1+2")
        assert e.source == "1+2"

# ─── Errors ───────────────────────────────────────────────────────────────────

class TestErrors:
    def test_compile_typeerror(self):
        with pytest.raises(TypeError): compile_expr(123)
    def test_div_zero(self):
        with pytest.raises(ExprEvalError): ev("1/0")
    def test_mod_zero(self):
        with pytest.raises(ExprEvalError): ev("1%0")
    def test_sqrt_neg(self):
        with pytest.raises(ExprEvalError): ev("sqrt(-1)")
