        assert ei.value.position == 0
    def test_unclosed_paren(self):
        with pytest.raises(ExprSyntaxError) as ei: compile_expr("(1+2")
        assert ei.value.position == 4
    def test_extra_rparen(self):
        with pytest.raises(ExprSyntaxError) as ei: compile_expr("1+2)")
        assert ei.value.position == 3
    def test_empty_paren(self):
        with pytest.raises(ExprSyntaxError) as ei: compile_expr("()")
        assert ei.value.position == 1
    def test_trailing_comma(self):
        with pytest.raises(ExprSyntaxError) as ei: compile_expr("max(1,)")
        assert ei.value.position == 6
    def test_number_ident(self):
        with pytest.raises(ExprSyntaxError) as ei: compile_expr("2x")
        assert ei.value.position == 1
    def test_double_dot(self):
        with pytest.raises(ExprSyntaxError) as ei: compile_expr("1..2")
        assert ei.value.position == 2
    def test_bad_exp(self):
